actions.script:
const escape = (line) => line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const text = String(bodyText || '').replace(/\r\n?/g, '\n').trim()
if (!text) ec.message.addError(ec.l10n.localize('Write a message first'))
else if (ec.service.sync().name('org.moqui.chat.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId || '').call()?.canRead
        && ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId || '').condition('encrypted', 'Y').count())
    ec.message.addError(ec.l10n.localize('This room is end-to-end encrypted: open it in a browser to write in it'))
else ec.service.sync().name('org.moqui.comms.ChatScreenServices.send#ChatMessage').parameters({chatRoomId: chatRoomId || '',
    body: text.split(/\n{2,}/).map((part) => '<p>' + part.split('\n').map(escape).join('<br>') + '</p>').join('')}).call()

for (const id of String(deliveryIds || '').split(',').map((part) => part.trim()).filter((part) => part)) {
    ec.service.sync().name('org.moqui.chat.ChatBridgeServices.retry#Delivery').parameter('chatBridgeDeliveryId', id).call()
    if (ec.message.hasError()) break
}
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize('Sending again'), 'success')

const when = (millis) => millis ? ec.l10n.format(new Date(Number(millis)), 'MMM d, h:mm a') : ''
// a membership, system, pin, call or poll event in words, as the browser's Chat.qvue systemText says it
const fill = (text, values) => String(ec.l10n.localize(text)).replace(/\{(\w+)\}/g, (match, key) => (values[key] == null ? '' : String(values[key])))
const systemText = (event, names) => {
    const content = event.content || {}
    const nameOf = (id) => (id ? names[id] || id : ec.l10n.localize('Someone'))
    const by = nameOf(content.byUserId || event.senderUserId)
    const user = nameOf(content.userId || content.chatActorId)
    const roles = {CmrOwner: 'an owner', CmrModerator: 'a moderator', CmrMember: 'a member', CmrAgent: 'an agent'}
    if (event.type === 'membership') {
        if (content.action === 'join') return fill('{user} joined', {user})
        if (content.action === 'add') return fill('{by} added {user}', {by, user})
        if (content.action === 'leave') return fill('{user} left', {user})
        if (content.action === 'remove') return fill('{by} took {user} out', {by, user})
        if (content.action === 'role' && content.automatic) return fill('{user} became an owner when {by} left', {by, user})
        if (content.action === 'role') return fill('{by} made {user} {role}', {by, user, role: roles[content.roleEnumId] ? ec.l10n.localize(roles[content.roleEnumId]) : content.roleEnumId})
        return fill('{by} changed the members', {by})
    }
    if (event.type === 'system') {
        if (content.action === 'created') return fill('{by} created the room', {by})
        if (content.action === 'renamed') return fill('{by} renamed the room to {name}', {by, name: content.roomName || ''})
        if (content.action === 'topic') return content.topic ? fill('{by} set the topic: {topic}', {by, topic: content.topic}) : fill('{by} cleared the topic', {by})
        if (content.action === 'archived') return fill('{by} archived the room', {by})
        if (content.action === 'unarchived') return fill('{by} took the room out of the archive', {by})
        return fill('{by} changed the room', {by})
    }
    if (event.type === 'pin') return fill(content.pinned ? '{by} pinned a message' : '{by} unpinned a message', {by})
    if (event.type === 'call') return fill('{by} started a call', {by})
    if (event.type === 'poll') return fill('{by} made a poll', {by})
    return by
}
roomList = []
eventList = []
room = null
canPost = false
canJoin = false
encryptedRoom = false
e2eeText = ''
unreadTotal = 0
bridgeText = ''
notConnected = false
if (chatRoomId) {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#RoomView').parameters({chatRoomId: chatRoomId, limit: 30}).call()
    if (!ec.message.hasError() && out.room) {
        room = out.room
        encryptedRoom = !!room.encrypted
        canPost = !!(out.access && out.access.canPost) && !encryptedRoom
        canJoin = !!(out.access && out.access.canJoin)
        const canModerate = !!(out.access && out.access.canModerate)
        // each mapping: its network, the room's name there and which way messages go (they are set in the browser)
        const WAYS = {CrbIn: ec.l10n.localize('only in'), CrbOut: ec.l10n.localize('only out')}
        const networks = Array.from(new Set(Array.from(room.bridges || []).map((bridge) => (bridge.networkName || bridge.name || '')
            + (bridge.externalRoomName || WAYS[bridge.directionEnumId] ? ' (' + [bridge.externalRoomName, WAYS[bridge.directionEnumId]].filter((part) => part).join(', ') + ')' : ''))
            .filter((name) => name)))
        bridgeText = networks.length ? ec.resource.expand(ec.l10n.localize('Messages here also go to ${names}'), '', {names: networks.join(', ')}) : ''
        notConnected = !!room.notConnected
        // the room's E2EE label as one line: the rule of moqui.chat.e2eeLabel (Comms-Messaging §6.2), with no device
        // trust, which only a browser knows
        const roomBridges = Array.from(room.bridges || [])
        const sms = room.roomTypeEnumId === 'CrtExternal' || roomBridges.some((bridge) => bridge.network === 'sms')
        const otherBridge = roomBridges.some((bridge) => bridge.network !== 'sms')
        // a record's room kept to its members is a plain private room
        const open = room.roomTypeEnumId === 'CrtPublic' || ['CrvUsers', 'CrvRecord'].includes(room.visibilityEnumId)
            || (room.roomTypeEnumId === 'CrtRecord' && room.visibilityEnumId !== 'CrvMembers')
        e2eeText = ec.l10n.localize(encryptedRoom ? 'End-to-end encrypted'
            : sms && otherBridge ? 'Not end-to-end encrypted. Texts go through the phone network and the SMS provider, and the bridge reads messages to pass them on.'
            : sms ? 'Not end-to-end encrypted. Texts go through the phone network and the SMS provider.'
            : room.bridged ? 'Not end-to-end encrypted on this server. The bridge reads messages to pass them on.'
            : open ? 'Not end-to-end encrypted: the server can read this room'
            : 'Not end-to-end encrypted. The server can read these messages.')
        const STATES = {accepted: 'Delivered', pending: 'Sending', failed: 'Not delivered', uncertain: 'May not have arrived'}
        const page = out.timeline || {}
        const names = page.userNames || {}
        eventList = Array.from(page.eventList || []).map((event) => {
            const files = event.encrypted ? [] : Array.from(event.attachments || []).map((file) => file.fileName || file.name || '').filter((name) => name)
            // a message of someone the user blocked (plans/Comms-Messaging.md §18.3 phase 11): its line says so, nothing of it shows
            let text = event.hidden ? ec.l10n.localize('Hidden: a message from someone you blocked')
                : event.redacted ? (event.removedLabel || ec.l10n.localize('Message removed'))
                : event.viewOnce ? ec.l10n.localize('View-once photo: open it in the app')
                : event.encrypted ? ec.l10n.localize('Encrypted message')
                : (event.bodyText || (event.poll ? ec.l10n.localize('Poll') + ': ' + (event.poll.question || '') : ''))
            if (files.length) text = (text ? text + ' ' : '') + '[' + files.join(', ') + ']'
            if (!text && event.type !== 'message') text = systemText(event, names)
            if (event.edited) text += ' ' + ec.l10n.localize('(edited)')
            // a disappearing message (plans/Comms-Messaging.md §18.3 phase 16): the terminal keeps nothing, and says so
            if (event.expireDate != null) text += ' · ' + ec.l10n.localize('disappears')
            if (Number(event.threadReplyCount || 0) > 0) text += ' · ' + event.threadReplyCount + ' ' + ec.l10n.localize(event.threadReplyCount == 1 ? 'reply' : 'replies')
            const delivery = event.delivery || null
            const failed = delivery ? Array.from(delivery.destinations || []).find((destination) => destination.error && destination.state !== 'accepted') : null
            const retryIds = delivery && delivery.retryable && (event.senderUserId === ec.user.userId || canModerate)
                    ? Array.from(delivery.destinations || []).filter((destination) => destination.retryable).map((destination) => destination.chatBridgeDeliveryId).join(',') : ''
            return {eventSeq: event.eventSeq, isMessage: event.type === 'message', senderName: (event.senderName || names[event.senderUserId] || '')
                    + (event.senderExternal ? ' (' + (event.senderExternal.networkName || ec.l10n.localize('Outside')) + ')' : ''),
                timeText: when(event.sentDate), text: text,
                deliveryText: delivery ? ec.l10n.localize(STATES[delivery.state] || delivery.state) + (failed ? ': ' + failed.error : '') : '',
                retryIds: retryIds}
        })
    }
} else {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatData').parameter('limit', limit ? Number(limit) : 200).call()
    if (!ec.message.hasError()) {
        unreadTotal = out.unreadTotal || 0
        roomList = Array.from(out.roomList || []).map((item) => {
            const last = item.lastMessage || null
            const counts = [Number(item.unreadCount || 0) > 0 ? item.unreadCount + ' ' + ec.l10n.localize('unread') : '',
                Number(item.mentionCount || 0) > 0 ? '@' + item.mentionCount : ''].filter((part) => part).join(' ')
            const bridged = item.bridged ? ' [' + (Array.from(item.bridgeNetworkNames || []).join(', ') || ec.l10n.localize('bridged'))
                    + (item.notConnected ? ', ' + ec.l10n.localize('not connected') : '') + ']' : ''
            return {chatRoomId: item.chatRoomId, nameText: (item.isPinned ? '* ' : '') + (item.displayName || item.roomName || item.chatRoomId) + bridged
                    + (item.isMuted ? ' ' + ec.l10n.localize('(muted)') : ''),
                countText: counts, lastText: last ? (last.senderName ? last.senderName + ': ' : '') + (last.encrypted ? ec.l10n.localize('Encrypted message') : last.snippet || '') : '',
                timeText: last ? when(last.sentDate) : ''}
        })
    }
}
// Info of one message (infoSeq): the event read again with the members' read markers (get#Timeline, which checks
// the room), as moqui.chat.messageInfo words it in the browser
infoList = []
infoNote = ''
if (room && infoSeq) {
    const page = ec.service.sync().name('org.moqui.chat.ChatServices.get#Timeline').parameters({chatRoomId: chatRoomId,
        eventSeq: Number(infoSeq), limit: 1}).call() || {}
    const event = Array.from(page.eventList || []).find((one) => Number(one.eventSeq) === Number(infoSeq))
    if (event && event.type === 'message') {
        const say = (label, text) => infoList.push({label: ec.l10n.localize(label), text: text})
        say('Sent', ec.l10n.format(new Date(Number(event.sentDate)), 'MMM d, yyyy, h:mm a'))
        if (event.senderExternal) say('Came from', event.senderExternal.networkName || event.senderExternal.network || '')
        const RECEIPTS = {delivered: "Delivered: the network's receipt says so", sent: 'Sent on by the network',
            unconfirmed: 'Taken by the network; it has not confirmed delivery'}
        const STATES = {pending: 'Sending', failed: 'Not delivered', uncertain: 'May not have arrived'}
        const destinations = Array.from((event.delivery && event.delivery.destinations) || [])
        // two bridges of one network are told apart by their own names
        const network = (one) => one.networkName || one.bridgeName || ec.l10n.localize('Bridge')
        const repeats = (name) => destinations.filter((one) => network(one) === name).length > 1
        for (const one of destinations) {
            const text = one.state === 'accepted' ? ec.l10n.localize(RECEIPTS[one.receipt] || 'Taken by the network')
                : ec.l10n.localize(STATES[one.state] || one.state)
            infoList.push({label: repeats(network(one)) && one.bridgeName && one.bridgeName !== network(one) ? network(one) + ' · ' + one.bridgeName : network(one),
                text: text + (one.error && one.state !== 'accepted' ? ': ' + one.error : '')})
            // an RCS bridge's: the way it went (plans/Comms-Messaging.md §16)
            const PATHS = {rcs: 'RCS', sms: 'SMS: the phone did not take RCS', mms: 'MMS: the phone did not take RCS'}
            if (PATHS[one.path]) say('Sent as', ec.l10n.localize(PATHS[one.path]))
        }
        const thread = event.threadRootEventSeq != null
        if (thread) infoNote = ec.l10n.localize('A thread has no read receipts.')
        else if (ec.user.getPreference('CHAT_READ_RECEIPTS') === 'N') say('Read by', ec.l10n.localize('Your read receipts are off, so you do not see who has read it'))
        else {
            const readers = Array.from(page.memberList || []).filter((member) => member.userId && member.userId !== ec.user.userId
                    && member.userId !== event.senderUserId && !member.isAgent && member.lastReadEventSeq != null
                    && Number(member.lastReadEventSeq) >= Number(event.eventSeq)
                    // one who joined after it has a marker past it (a join reads to the latest) but never read it
                    && (member.joinedDate == null || Number(member.joinedDate) <= Number(event.sentDate))).map((member) => member.name || member.userId)
            say('Read by', !readers.length ? ec.l10n.localize('No one yet, of those with read receipts on')
                : readers.slice(0, 8).join(', ') + (readers.length > 8 ? ' ' + fill('and {count} more', {count: readers.length - 8}) : ''))
            infoNote = ec.l10n.localize('People with read receipts off are not listed. Read by means read up to here or later.')
        }
        infoNote = (infoNote ? infoNote + ' ' : '') + ec.l10n.localize("Delivery to each person's devices is not known to the server.")
    }
}
// the room's Links (chatView links), newest first, and More by the cursor
linkList = []
linksNext = null
showLinks = !!(room && chatView === 'links')
if (showLinks && !encryptedRoom) {
    const out = ec.service.sync().name('org.moqui.chat.ChatServices.find#RoomLinks').parameters({chatRoomId: chatRoomId, limit: 40,
        beforeEventSeq: linksBefore ? Number(linksBefore) : null}).call()
    if (!ec.message.hasError()) {
        linksNext = out.nextBeforeEventSeq ?? null
        linkList = Array.from(out.links || []).map((link) => ({url: link.url, titleText: [link.title, link.siteName].filter((part) => part).join(' · '),
            senderName: link.senderName || '', timeText: when(link.sentDate)}))
    }
}
// my Activity across rooms (chatView activity, no room): mentions, replies and reactions, newest first
activityList = []
activityNext = null
// and the Threads I am in (chatView threads: ChatScreenServices.find#ChatThreads, one row per thread, the latest
// reply first, paged by its own cursor)
showThreads = !chatRoomId && chatView === 'threads'
showActivity = !chatRoomId && (chatView === 'activity' || showThreads)
if (showThreads) {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.find#ChatThreads').parameters({limit: 40,
        cursor: activityCursor || null}).call()
    if (!ec.message.hasError()) {
        activityNext = out.nextCursor ?? null
        activityList = Array.from(out.items || []).map((item) => ({chatRoomId: item.chatRoomId,
            kindText: item.startedByMe ? ec.l10n.localize('Your thread') : ec.l10n.localize('A thread you replied in'),
            roomText: item.roomName || item.chatRoomId, actorName: item.lastUserName || '',
            snippet: item.encrypted ? ec.l10n.localize('Encrypted message') : item.lastSnippet || item.rootSnippet || '', timeText: when(item.lastDate)}))
    }
} else if (showActivity) {
    const out = ec.service.sync().name('org.moqui.chat.ChatServices.find#ChatActivity').parameters({limit: 40,
        cursor: activityCursor || null}).call()
    if (!ec.message.hasError()) {
        activityNext = out.nextCursor ?? null
        const KINDS = {mention: 'Mentioned you', reply: 'Replied to you', threadReply: 'Replied in a thread', reaction: 'Reacted to your message'}
        activityList = Array.from(out.items || []).map((item) => ({chatRoomId: item.chatRoomId,
            kindText: ec.l10n.localize(KINDS[item.kind] || item.kind) + (item.reactionKey ? ' ' + item.reactionKey : ''),
            roomText: item.roomName || item.chatRoomId, actorName: item.actorName || '',
            snippet: item.encrypted ? ec.l10n.localize('Encrypted message') : item.snippet || '', timeText: when(item.date)}))
    }
}
roomTitle = room ? (room.displayName || room.roomName || chatRoomId) : ''
roomTopic = room && room.topic ? room.topic : ''
chatDraft = {chatRoomId: chatRoomId || '', bodyText: ''}
